"""Build small, original local SVG trainer sprites and the map's healing building."""
from pathlib import Path
p=Path(__file__).resolve().parents[1]/'assets'
(p/'trainers').mkdir(exist_ok=True)
styles=[('fern','#79a55d','#c8db96','#765533','cap'),('milo','#547ead','#eac47f','#53382c','cap'),('iris','#9879bb','#ead99a','#554263','hair'),('hugo','#ad8353','#e3c6a2','#654435','hat'),('ruby','#cf5f52','#f0c48f','#713d29','cap'),('ashby','#7a7e93','#a7cbbb','#3c3434','hat'),('skye','#80b9c9','#f2eadb','#786659','beanie'),('marin','#5c8baf','#dce9c6','#35485b','hair')]
for name,coat,trim,hair,hat in styles:
 headwear={'cap':f'<path d="M19 27V18Q21 7 40 7q18 0 20 14v9H19Z" fill="{coat}"/><path d="M16 27h47v7H15Z" fill="{trim}"/><path d="M37 11h9v12h-9Z" fill="{trim}"/>','hat':f'<path d="M24 24l4-15h24l5 15Z" fill="{trim}"/><path d="M13 24h54v9H13Z" fill="{coat}"/><path d="M25 19h31v5H25Z" fill="{coat}"/>','beanie':f'<path d="M19 29V22Q20 7 40 7t21 22Z" fill="{coat}"/><path d="M18 24h44v9H18Z" fill="{trim}"/><circle cx="40" cy="7" r="6" fill="{trim}"/>','hair':f'<path d="M18 33V24Q17 6 38 8q23-4 25 20v29l-9 2-4-28-9-9-8 10Z" fill="{hair}"/>'}[hat]
 svg=f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 80 96"><ellipse cx="40" cy="89" rx="25" ry="6" fill="#143a3540"/><g stroke="#293c46" stroke-width="2" stroke-linejoin="round"><path d="M24 66h14v22H23l-2-5Zm19 0h13l3 18-2 4H42Z" fill="#3c5062"/><path d="M22 82h17v8H20v-5m22-3h16l3 8H42Z" fill="#34414b"/><path d="M24 47h33l4 24-8 6H27l-8-6Z" fill="{coat}"/><path d="M29 47h22l-4 14H34Z" fill="{trim}"/><path d="M36 51h8v21h-8Z" fill="{coat}"/><path d="M17 49l9 4-5 20-9-3Zm39 2 8-2 5 21-9 3Z" fill="{coat}"/><path d="M12 65l10 3-1 9-8-1Zm47 3 10-3-1 11-8 1Z" fill="#efc7a3"/><path d="M20 23q20-14 40 0v17q-2 15-20 16-18-1-20-16Z" fill="#f1cda9"/><path d="M19 26h7v13h-6m35-13h6v13h-5" fill="{hair}"/>{headwear}<path d="M28 36h5v7h-5Zm19 0h5v7h-5Z" fill="#263945" stroke="none"/><path d="M36 47q4 3 8 0" fill="none" stroke-width="1.7"/><circle cx="26" cy="46" r="3" fill="#e69c8e" stroke="none"/><circle cx="54" cy="46" r="3" fill="#e69c8e" stroke="none"/><path d="M26 60h9v10h-9Z" fill="{trim}"/><circle cx="53" cy="65" r="5" fill="#f4eee1"/><path d="M48 65h10m-5-5v5" stroke="#b65f59"/></g></svg>'''
 (p/'trainers'/f'{name}.svg').write_text(svg)
(p/'pokemon-center.svg').write_text('''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 144"><ellipse cx="80" cy="129" rx="75" ry="12" fill="#153e3540"/><g stroke="#344854" stroke-width="3" stroke-linejoin="round"><path d="M17 63h126v58H17Z" fill="#f5e9d3"/><path d="M17 98h126v23H17Z" fill="#d8cdb7"/><path d="M9 70 27 25h106l18 45Z" fill="#b84b52"/><path d="m15 54 12-29h106l12 29Z" fill="#ec7073"/><path d="M6 69h148v10H6Z" fill="#9f424b"/><path d="M36 15h88v27H36Z" fill="#f8f0dd"/><path d="M44 22h72v13H44Z" fill="#db5b64" stroke="none"/><path d="M27 87h28v22H27Zm78 0h28v22h-28Z" fill="#88c8d1"/><path d="M30 90h23v5H30Zm78 0h23v5h-23Z" fill="#d4efeb" stroke="none"/><path d="M63 88h34v35H63Z" fill="#4b727e"/><path d="M69 93h22v29H69Z" fill="#b1dce0"/><path d="M80 94v28" fill="none"/><path d="M56 124h48v8H56Z" fill="#b4baa9"/><circle cx="80" cy="65" r="18" fill="#faf4e7"/><path d="M62 65a18 18 0 0 1 36 0Z" fill="#e45e68"/><path d="M62 65h36"/><circle cx="80" cy="65" r="6" fill="#faf4e7"/><path d="M10 112h8v17H6v-12m136-5h8l4 17h-12Z" fill="#759958"/></g></svg>''')
print('Built 8 trainer sprites and Pokémon Center building.')
